<script lang="ts">import { resolve } from '$app/paths'; import EvidenceBadge from '$lib/components/EvidenceBadge.svelte'; let { data } = $props(); let maxScore = $derived(Math.max(...data.runs.map((run: any) => run.score.passed / run.score.total), 0));</script>
<svelte:head><title>{data.model.name} — MetalBench</title><meta name="description" content={data.model.summary} /></svelte:head>
<section class="page-head"><p class="eyebrow">MODEL FILE / {data.model.family}</p><h1>{data.model.name}</h1><p class="lede">{data.model.summary}</p><dl class="facts three"><div><dt>Parameters</dt><dd>{data.model.parameterCount.totalBillions}B total · {data.model.parameterCount.activeBillions}B active</dd></div><div><dt>Architecture</dt><dd>{data.model.architecture} · {data.model.quant.family} {data.model.quant.bits}-bit</dd></div><div><dt>Modalities</dt><dd>{data.model.modalities.join(' · ')}</dd></div></dl></section>
