<section class="section"><div class="section-head"><div><p class="eyebrow">RUN HISTORY</p><h2>{data.runs.length} recorded {data.runs.length === 1 ? 'run' : 'runs'}</h2></div></div><div class="model-run-list">{#each data.runs as run (run.id)}<a href={resolve(`/runs/${run.id}/`)}><span><EvidenceBadge level={run.evidence.level} /><strong>{run.benchmarkSlug}</strong><small>{run.runtime.name} · {run.runtime.quant}</small></span><i><b style:width={`${maxScore ? (run.score.passed / run.score.total) / maxScore * 100 : 0}%`}></b></i><span class="bar-value">{run.score.passed}/{run.score.total}</span></a>{/each}</div></section>
